    historicoNumero: 6,
    destinatario: { nome: "Anna Maria Trievi", qualificacao: "sobrinha e religiosa em Santa Lucia", tratamento: "Nipote carissima" },
    local: "Florença",
    data: { iso: "1576-10-17", original: "Roma, il dì 17 ottobre 1576.", aproximada: false },
